#include <zephyr/ztest.h>
#include <zephyr/log/log.h>

enum numbers {
	ZERO, ONE, TWO, THREE, FOUR, FIVE, SIX, SEVEN, EIGHT, NINE, TEN
};

LOG_ENUM_MAP_DEFINE(numbers_map,
	LOG_ENUM_MAP_ENTRY(ZERO),
	LOG_ENUM_MAP_ENTRY(ONE),
	LOG_ENUM_MAP_ENTRY(TWO),
	LOG_ENUM_MAP_ENTRY(THREE),
	LOG_ENUM_MAP_ENTRY(FOUR),
	LOG_ENUM_MAP_ENTRY(FIVE),
	LOG_ENUM_MAP_ENTRY(SIX),
	LOG_ENUM_MAP_ENTRY(SEVEN),
	LOG_ENUM_MAP_ENTRY(EIGHT),
	LOG_ENUM_MAP_ENTRY(NINE),
	LOG_ENUM_MAP_ENTRY(TEN)
);

ZTEST(enum_mgmt, test_count)
{
	int count = log_enum_count_get(numbers_map);
	/* Buffer used for printing, make it large enough. */
	char buf[32];

	snprintf(buf, sizeof(buf), "Count is %d", count);
	printk("%s\n", buf);

	zassert_equal(count, 11, "Unexpected count");
}

ZTEST(enum_mgmt, test_details)
{
	zassert_str_equal(log_enum_str_get(numbers_map, TEN), "TEN", "Wrong string for TEN");
	zassert_str_equal(log_enum_str_get(numbers_map, ZERO), "ZERO", "Wrong string for ZERO");

	/* Check out of bounds access */
	zassert_is_null(log_enum_str_get(numbers_map, 11), "Should be null for out of bounds");
	zassert_is_null(log_enum_str_get(numbers_map, -1), "Should be null for negative value");
}

ZTEST_SUITE(enum_mgmt, NULL, NULL, NULL, NULL, NULL);
